solution.javascript:
function copyRandomList(head) {
  if (!head) return null;
  const map = new Map();
  let cur = head;
  while (cur) { map.set(cur, new Node(cur.val)); cur = cur.next; }
  cur = head;
  while (cur) {
    map.get(cur).next = cur.next ? map.get(cur.next) : null;
    map.get(cur).random = cur.random ? map.get(cur.random) : null;
    cur = cur.next;
  }
  return map.get(head);
}

solution.cpp:
Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    unordered_map<Node*, Node*> map;
    for (Node* cur = head; cur; cur = cur->next) map[cur] = new Node(cur->val);
    for (Node* cur = head; cur; cur = cur->next) {
        map[cur]->next = cur->next ? map[cur->next] : nullptr;
        map[cur]->random = cur->random ? map[cur->random] : nullptr;
    }
    return map[head];
}
